{"path": "ranges.mjs", "content": "export function mergeRanges(ranges) {
  if (!Array.isArray(ranges)) {
    throw new TypeError('ranges must be an array');
  }

  const pairs = ranges.map((pair) => {
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw new TypeError('each range must be a [start, end] pair');
    }
    const [start, end] = pair;
    if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end)) {
      throw new TypeError('range bounds must be safe integers');
    }
    if (start > end) {
      throw new TypeError('range start must be <= end');
    }
    return [start, end];
  });

  if (pairs.length === 0) return [];

  pairs.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const result = [[pairs[0][0], pairs[0][1]]];
  for (let i = 1; i < pairs.length; i += 1) {
    const [start, end] = pairs[i];
    const last = result[result.length - 1];
    if (start <= last[1] + 1) {
      if (end > last[1]) last[1] = end;
    } else {
      result.push([start, end]);
    }
  }

  return result;
}
